<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script>
const adminCsrf=<?=json_encode($csrf)?>;
const dailyRows=<?=json_encode($daily??[],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const catRows=<?=json_encode($categoryStats??[],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
if(window.Chart){const labels=[];const vals=[];const map={};dailyRows.forEach(r=>map[r.day]=Number(r.total));for(let n=13;n>=0;n--){let d=new Date();d.setDate(d.getDate()-n);let k=d.toISOString().slice(0,10);labels.push(k.slice(5));vals.push(map[k]||0);}new Chart(document.getElementById('reportsChart'),{type:'line',data:{labels,datasets:[{label:'Reports',data:vals,tension:.3,fill:true}]},options:{responsive:true,plugins:{legend:{display:false}}}});new Chart(document.getElementById('categoryChart'),{type:'doughnut',data:{labels:catRows.map(r=>r.name),datasets:[{data:catRows.map(r=>Number(r.total))}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});}
async function adminAction(payload){if(!confirm('Apply this administrative action?'))return;const r=await fetch('/neighbournet/api/admin/manage.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({...payload,csrf_token:adminCsrf})});const j=await r.json();alert(j.message||'Request completed');if(j.success)location.reload();}
function showIncidentAdminFromButton(button,id,status){showIncidentAdmin(id,button.dataset.title,status,button.dataset.reviewFlag||'none',button.dataset.reviewNote||'');}
function showIncidentAdmin(id,title,status,flag='none',flagNote=''){document.getElementById('manageIncidentId').value=id;document.getElementById('manageIncidentTitle').textContent='#'+id+' · '+title;document.getElementById('manageIncidentStatus').value=status;document.getElementById('manageIncidentNote').value='';document.getElementById('managePrivateNote').value='';document.getElementById('manageIncidentFlag').value=flag;document.getElementById('manageIncidentFlagNote').value=flagNote;bootstrap.Modal.getOrCreateInstance(document.getElementById('incidentAdminModal')).show();}
async function saveIncidentStatus(){await adminAction({action:'status',incident_id:Number(document.getElementById('manageIncidentId').value),status:document.getElementById('manageIncidentStatus').value,note:document.getElementById('manageIncidentNote').value});}
async function saveIncidentNote(){await adminAction({action:'note',incident_id:Number(document.getElementById('manageIncidentId').value),note:document.getElementById('managePrivateNote').value});}
async function saveIncidentFlag(){await adminAction({action:'flag_incident',incident_id:Number(document.getElementById('manageIncidentId').value),flag:document.getElementById('manageIncidentFlag').value,note:document.getElementById('manageIncidentFlagNote').value});}
</script>
